const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const notes=new URLSearchParams(location.search).has('notes');
let state={index:0,sub:0,total:0,elapsed:0,running:false,auto:false,stamp:Date.now()},last=Date.now(),lastSeen=0;
const clock=ms=>{const s=Math.floor(Math.max(0,ms)/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`};
const ACT={1:[[1,'Lista enlazada por hashes',3],[2,'Una red distribuida',3]],2:[[3,'Anatomía de un bloque',5],[9,'Muchas transacciones, una huella',3],[4,'Árbol de Merkle',3],[10,'La firma autoriza el bloque',3]],3:[[5,'Inmutabilidad por encadenamiento',3]],4:[[6,'Tres modelos de consenso',3],[7,'SCP y quórums de confianza',3]],5:[[11,'Cada nodo elige en quién confía',3],[12,'Los quórums se superponen',3],[13,'Sin reorganizaciones',3]],6:[[14,'Un par de claves',3],[15,'Una cuenta, muchos activos',3],[16,'El sequence number evita repetir',3]],7:[[17,'Los verbos de Stellar',5],[18,'Una transacción, varias operaciones',3],[19,'Atómica: todo o nada',3]],8:[[20,'Del código al ledger',3],[21,'Un sandbox en la red',3],[22,'Reglas para agentes',3]]},actTotal=i=>ACT[i].reduce((n,x)=>n+x[2],0);
const step=n=>{for(const [h,t,c] of ACT[state.index]||[]){if(n<c)return{slide:h,beat:n,title:t};n-=c}};
const ACT_BTN={1:[['Bloque 1','[data-selectblock]|0'],['Bloque 2','[data-selectblock]|1'],['Bloque 3','[data-selectblock]|2']],2:[['↺ Repetir animación','#syncBtn|0']],3:[['prev_hash','[data-field]|0'],['timestamp','[data-field]|1'],['merkle_root','[data-field]|2'],['nonce / validator_sig','[data-field]|3']],4:[1,2,3,4].map(n=>['TX 0'+n,'[data-tx]|'+(n-1)]),5:[['⚡ Alterar / restaurar bloque 02','#tamperBtn|0']],6:[['Bitcoin · PoW','[data-compare]|0'],['Ethereum · PoS','[data-compare]|1'],['Stellar · SCP','[data-compare]|2']],7:[['✦ Simular / reiniciar acuerdo','#agreeBtn|0']],9:[['↺ Repetir animación','#txBtn|0']],10:[['⚡ Alterar / restaurar bloque','#sigBtn|0']],11:[['↺ Repetir animación','#rp11|0']],12:[['↺ Repetir animación','#rp12|0']],13:[['↺ Repetir animación','#rp13|0']],14:[['↺ Repetir animación','#rp14|0']],15:[['↺ Repetir animación','#rp15|0']],16:[['↺ Repetir animación','#rp16|0']],18:[['↺ Repetir animación','#rp18|0']],19:[['↺ Repetir animación','#rp19|0']],17:[],20:[['↺ Repetir animación','#rp20|0']],21:[['↺ Repetir animación','#rp21|0']],22:[['↺ Repetir animación','#rp22|0']]};
let lastAct=null;
function sendAct(name){const f=$('#act2'),[sel,i]=name.split('|');if(f&&f.dataset.ready)f.contentWindow.postMessage({type:'click',sel,i:Number(i)},'*')}
function subPanel(){const el=$('#subpanel');if(!el)return;if(!ACT[state.index]){el.innerHTML=`<h3>Slides interactivas</h3><div class="act-row">${Object.keys(ACT).map(i=>`<button data-go="${i}">Slide ${+i+1} →</button>`).join('')}</div>`;return}const cur=step(state.sub||0);let n=0,rows='';for(const [h,t,c] of ACT[state.index]){rows+=`<div class="sub-row"><span>${esc(t)}</span><div>`;for(let k=0;k<c;k++,n++)rows+=`<button data-sub="${n}" class="${n===state.sub?'active':''}">${k+1}</button>`;rows+='</div></div>'}el.innerHTML=`<h3>Sub-slides de la slide ${state.index+1} · en vivo</h3><div class="sub-nav"><button data-cmd="prev">◀ Sub-slide anterior</button><b>Paso ${(state.sub||0)+1} de ${actTotal(state.index)}</b><button data-cmd="next">Sub-slide siguiente ▶</button></div>${rows}${ACT_BTN[cur.slide].length?`<h3>Interacción · ${esc(cur.title)}</h3><div class="act-row">${ACT_BTN[cur.slide].map(([l,v])=>`<button data-act="${v}">${esc(l)}</button>`).join('')}</div>`:''}`}
function syncSub(){const f=$('#act2'),p=step(state.sub||0);if(f&&f.dataset.ready&&p)f.contentWindow.postMessage({type:'step',slide:p.slide,beat:p.beat,parent:state.index+1},'*')}
function mountAct2(){let f=$('#act2');if(!ACT[state.index]){f?.remove();return}if(f)return syncSub();f=document.createElement('iframe');f.id='act2';f.src='acto2.html?slide=1';f.title='Blockchain interactivo';f.onload=()=>{f.dataset.ready=1;syncSub()};$('#deck').append(f)}
function render(){const s=slides[state.index];$('#counter').textContent=`${String(state.index+1).padStart(2,'0')} / 18`;$('#section').textContent=s.section;$('#prev').disabled=state.index===0;$('#next').disabled=state.index===17;$('#progress').style.width=`${(state.index+1)/18*100}%`;
if(notes){$('#script').innerHTML=`<span class="eyebrow">${esc(s.section)} · Página ${state.index+1} de ${slides.length}</span><h1>${esc(s.title)}</h1><p class="sub">En pantalla: ${esc(s.sub)}</p><div>${esc(s.script??s.notes??'')}</div>${ACT[state.index]?`<p class="sub">Paso ${(state.sub||0)+1} de ${actTotal(state.index)} · ${esc(step(state.sub||0).title)}</p>`:''}<p class="sub">Sigue: ${esc(slides[state.index+1]?.title||'Fin de la charla')}</p>`;subPanel();$('#index').innerHTML=slides.map((x,i)=>`<button class="${i===state.index?'active':''}" data-go="${i}" title="${esc(x.title)}">${i+1}</button>`).join('');return}
document.body.dataset.kind=s.kind;document.body.dataset.slide=state.index;
const wide=['chain','broken','metrics','flow'].includes(s.kind);
let content='';
if(s.kind==='hero')content=`<div class="opening-line">Los agentes han despertado.</div><h1>Esta noche<br>le damos<br><em>billetera.</em></h1><p class="lead">${esc(s.sub)}</p><span class="ticket">UNA HISTORIA DE AGENTES & BLOCKCHAIN</span>`;
else {
 const heading=`<h1>${esc(s.title)}</h1><p class="lead">${esc(s.sub)}</p>`;
 let visual='';
 if(s.kind==='code')visual=`<div class="spellbook"><div class="book-label">GRIMORIO DEL DESARROLLADOR · ${state.index===14?'PSEUDOCÓDIGO':'NOTAS DE LABORATORIO'}</div><pre>${s.items.map((x,i)=>`<span><b>${String(i+1).padStart(2,'0')}</b><code>${esc(x)||' '}</code></span>`).join('')}</pre></div>`;
 else if(s.kind==='table')visual=`<div class="ledger"><table>${s.items.map((x,i)=>`<tr>${x.split('|').map(v=>i===0?`<th>${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</table></div>`;
 else if(s.kind==='network')visual=`<div class="coven">${s.items.slice(0,4).map((x,i)=>`<span class="sigil"><i>${['✦','☾','✧','☆'][i]}</i>${esc(x)}</span>`).join('')}</div><p class="aside-note">${esc(s.items[4])}</p>`;
 else if(s.kind==='closing')visual=`<div class="resource-scroll">${s.items.map(x=>`<a href="https://${x}" target="_blank" rel="noopener">${esc(x)} <span>↗</span></a>`).join('')}</div><p class="aside-note">Stellar es una marca de Stellar Development Foundation. Presentación comunitaria independiente.</p>`;
 else visual=`<div class="${s.kind==='flow'?'ritual':s.kind==='stack'?'incantation':'graveyard'}">${s.items.map((x,i)=>{const [a,b]=x.split('|');return `<div class="paper-piece"><span class="piece-rune">${s.kind==='flow'?String(i+1).padStart(2,'0'):['☾','✦','✧','☆'][i%4]}</span><strong>${esc(s.kind==='flow'?a.replace(/^\d+\s*·\s*/, ''):a)}</strong><p>${esc(b||'')}</p></div>`}).join('')}</div>`;
 content=heading+`<div class="visual">${visual}</div>`+(s.ask?`<p class="ask">${esc(s.ask)}</p>`:'')+(state.index===9?'<p class="aside-note">Mínimo clásico sin congestión. Soroban añade tarifas por recursos.</p>':'');
}
$('#stage').innerHTML=`<article class="slide ${wide?'composition-wide':'composition-split'} ${s.kind==='hero'?'opening':''}"><div class="chapter-label"><span>ACTO ${String(state.index+1).padStart(2,'0')}</span> ${esc(s.section)} <i>✦</i></div>${content}</article><div class="page-signature">HALLOWEEN / UMSA · LA PAZ / 29 OCT 2026</div><div class="folio">${String(state.index+1).padStart(2,'0')}<small> / 18</small></div>`;
mountAct2();window.dispatchEvent(new CustomEvent('slidechange',{detail:{index:state.index,kind:s.kind,wide}}))}

function tickUI(){const s=slides[state.index];$('#play').textContent=state.running?'Pausar':'Iniciar / continuar';$('#auto').classList.toggle('active',state.auto);$('#time').textContent=`${clock(state.total)} / 30:00`;if(notes){$('#automatic').checked=state.auto;$('#connection').textContent=Date.now()-lastSeen<2500?'● Conectado al servidor · control compartido':'Reconectando con el servidor…';$('#clocks').innerHTML=`<small>ESTA DIAPOSITIVA / PREVISTO</small><span class="${state.elapsed>s.seconds*1000?'late':''}">${clock(state.elapsed)} / ${clock(s.seconds*1000)}</span><small>TOTAL / PREVISTO</small>${clock(state.total)} / 30:00`}}
function applyState(next){if(next.stamp<state.stamp&&lastSeen)return;const changed=state.index!==next.index,subChanged=state.sub!==next.sub;state=next;lastSeen=Date.now();if(next.act){if(lastAct!==null&&next.act.n!==lastAct&&next.act.name&&!notes)sendAct(next.act.name);lastAct=next.act.n}if(changed){render();if(notes)window.scrollTo(0,0)}else if(subChanged){if(notes)render();else syncSub()}tickUI()}
async function command(type,index,name){try{const r=await fetch('/api/command',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type,index,name})});if(!r.ok)throw Error();applyState(await r.json())}catch{lastSeen=0;tickUI()}}
async function sync(){try{const r=await fetch('/api/state',{cache:'no-store'});if(!r.ok)throw Error();applyState(await r.json())}catch{lastSeen=0;tickUI()}finally{setTimeout(sync,250)}}
$('#presenter').onclick=e=>{const b=e.target.closest('[data-sub],[data-act],[data-cmd],[data-go]');if(!b)return;if(b.dataset.act)command('act',undefined,b.dataset.act);else if(b.dataset.cmd)command(b.dataset.cmd);else if(b.dataset.go)command('go',Number(b.dataset.go));else command('sub',Number(b.dataset.sub))};$('#notes').onclick=()=>window.open('?notes','stellar-notes');$('#prev').onclick=()=>command('prev');$('#next').onclick=()=>command('next');$('#play').onclick=()=>command('play');$('#auto').onclick=()=>command('auto');$('#reset').onclick=()=>command('reset');$('#automatic').onchange=()=>command('auto');$('#index').onclick=e=>{const b=e.target.closest('[data-go]');if(b)command('go',Number(b.dataset.go))};$('#full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const k=e.key.toLowerCase(),m={arrowright:'next',pagedown:'next',arrowleft:'prev',pageup:'prev',' ':'play',a:'auto',t:'reset'};if(m[k]){e.preventDefault();command(m[k])}if(k==='p')$('#notes').click();if(k==='f')$('#full').click()});
if(notes){document.body.classList.add('notes-mode');$('#presenter').hidden=false;$('#notes').textContent='Diapositivas ↗';$('#notes').onclick=()=>window.open('./','stellar-deck');document.body.insertBefore(document.querySelector('footer'),document.querySelector('#presenter'));document.querySelector('#presenter details').remove()}
render();tickUI();sync();
